def github_line_url(
    html_url: str | None,
    ref: str,
    path: str,
    start_line: int,
    end_line: int,
) -> str | None:
    if not html_url:
        return None

    return f"{html_url}/blob/{ref}/{path}#L{start_line}-L{end_line}"

